sp_widget.client_script:
api.controller = function($scope, $location, $window, $http) {
  var c = this;

  // Navigate to a portal page
  c.goTo = function(pageId) {
    $window.location.href = 'https://enablenowincdemo1.service-now.com/applicant?id=' + pageId;
  };

  // Badge class mapper
  c.getBadgeClass = function(state) {
    if (!state) return 'badge-draft';
    var map = {
      'under_review': 'badge-review',
      'draft':        'badge-draft',
      'approved':     'badge-approved',
      'submitted':    'badge-submitted',
      'rejected':     'badge-rejected'
    };
    return map[state.toLowerCase()] || 'badge-draft';
  };
}

sp_widget.css:
/* ═══════════════════════════════════════
   LAYOUT — sidebar + main content
═══════════════════════════════════════ */
.gn-layout {
  display: flex;
  min-height: 100vh;
  background: #f0f2f5;
}

.sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #fff;
  border-right: 5px solid #e5e7eb;
  position: sticky;
  top: 2%;
  height: 100vh;
  overflow-y: auto;
  z-index: 10;
  margin-top:-2%;
}

/* ESCAPE PORTAL CONTAINER */
.gn-layout {
  margin-left: -15px;
  margin-right: -15px;
  margin-top: 35px;
}

/* RESET */
.gn-layout *, .gn-layout *:before, .gn-layout *:after {
  box-sizing: border-box;
}

/* LAYOUT */
.gn-layout {
  display: flex;
  min-height: 100vh;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #f4f6fb;
  width: calc(100% + 30px);
  position: relative;
  align-items: flex-start;
}

/* ── MAIN ── */
.gn-main {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #f4f6fb;
  padding: 20px 24px 40px;
  flex: 1;
  min-height: 100vh;
  margin: 0;
  overflow-y: auto;
}

/* ── HERO BANNER ── */
.gn-banner {
  background: linear-gradient(135deg, #3D3180, #5443AD, #6B5FBF);
  border-radius: 16px;
  padding: 36px 48px 28px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
  color: #fff;
  min-height: 180px;
}
.gn-banner-top { display: flex; flex-direction: column; }
.gn-banner h2 {
  margin: 0 0 8px;
  font-size: 32px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.3px;
}
.gn-banner p {
  margin: 0;
  font-size: 15px;
  opacity: 0.88;
  color: #fff;
}
.gn-banner-btns { display: flex; gap: 12px; flex-wrap: wrap; }

.btn-primary {
  background: #fff;
  color: #5443AD;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: 8px;
  text-decoration: none;
  font-size: 13px;
  display: inline-block;
}
.btn-primary:hover { background: #EEEDFB; text-decoration: none; color: #5443AD; }

.btn-outline {
  border: 2px solid rgba(255,255,255,0.75);
  color: #fff;
  padding: 9px 20px;
  border-radius: 8px;
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
  display: inline-block;
}
.btn-outline:hover { background: rgba(255,255,255,0.15); text-decoration: none; color: #fff; }

/* ── SUMMARY CARDS ── */
.gn-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}
.gn-card-new {
  background: #fff;
  border-radius: 14px;
  padding: 18px 18px 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 10px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  border: 1px solid #f1f5f9;
  min-height: 148px;
}
.gn-card-new-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.gn-card-new-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  flex-shrink: 0;
}
.gn-card-new-icon.blue   { background: #EEEDFB; color: #5443AD; }
.gn-card-new-icon.orange { background: #fff7ed; color: #ea580c; }
.gn-card-new-icon.green  { background: #f0fdf4; color: #16a34a; }
.gn-card-new-icon.purple { background: #faf5ff; color: #7B6EC4; }

.gn-card-new-toptext {
  font-size: 11px;
  font-weight: 600;
  color: #9ca3af;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}
.gn-card-new-body { display: flex; flex-direction: column; gap: 2px; }
.gn-card-new-val  { font-size: 30px; font-weight: 700; color: #1e1e2e; line-height: 1.1; }
.gn-card-new-lbl  { font-size: 13px; color: #6b7280; margin-top: 2px; }
.gn-card-new-footer {
  font-size: 12px;
  font-weight: 500;
  padding-top: 8px;
  border-top: 1px solid #f1f5f9;
}

/* Color utilities */
.blue-text   { color: #5443AD !important; }
.orange-text { color: #ea580c !important; }
.green-text  { color: #16a34a !important; }
.purple-text { color: #7B6EC4 !important; }

/* ── TWO COLUMN GRID ── */
.gn-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 20px;
}

/* ── PANELS ── */
.gn-panel {
  background: #fff;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.05);
}
.gn-panel-hdr {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 15px;
  font-weight: 600;
  color: #1e1e2e;
  margin-bottom: 16px;
}
.gn-view-all { font-size: 13px; color: #5443AD; text-decoration: none; font-weight: 500; }
.gn-view-all:hover { text-decoration: underline; }

/* ── APP ROWS ── */
.gn-app-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 12px 0;
  border-bottom: 1px solid #f1f5f9;
}
.gn-app-row:last-child { border-bottom: none; }
.gn-app-name { font-size: 14px; font-weight: 600; color: #1e1e2e; }
.gn-app-id   { font-size: 12px; color: #6b7280; margin-top: 3px; }
.gn-app-time { font-size: 11px; color: #9ca3af; margin-top: 4px; }

/* ── BADGES ── */
.gn-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 11px;
  border-radius: 20px;
  white-space: nowrap;
  margin-left: 10px;
  flex-shrink: 0;
}
.badge-review    { background: #fff7ed; color: #ea580c; }
.badge-draft     { background: #f1f5f9; color: #475569; }
.badge-approved  { background: #f0fdf4; color: #16a34a; }
.badge-submitted { background: #EEEDFB; color: #5443AD; }
.badge-rejected  { background: #fef2f2; color: #dc2626; }

/* ── PROGRAM ROWS ── */
.gn-prog-row {
  padding: 12px 0;
  border-bottom: 1px solid #f1f5f9;
}
.gn-prog-row:last-child { border-bottom: none; }
.gn-prog-name   { font-size: 14px; font-weight: 600; color: #1e1e2e; }
.gn-prog-desc   { font-size: 12px; color: #6b7280; margin-top: 4px; }
.gn-prog-footer { display: flex; justify-content: space-between; margin-top: 8px; }
.gn-prog-budget { font-size: 12px; font-weight: 600; color: #1e1e2e; }
.gn-prog-close  { font-size: 12px; color: #9ca3af; }

/* ── QUICK ACTIONS ── */
.gn-qa-panel { margin-top: 0; }
.gn-qa-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
.gn-qa-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  background: #f9fafb;
  border-radius: 10px;
  border: 1px solid #e5e7eb;
  text-decoration: none;
  transition: background 0.15s;
}
.gn-qa-card:hover { background: #EEEDFB; text-decoration: none; }
.gn-qa-icon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}
.gn-qa-icon.blue   { background: #EEEDFB; color: #5443AD; }
.gn-qa-icon.green  { background: #f0fdf4; color: #16a34a; }
.gn-qa-icon.purple { background: #faf5ff; color: #7B6EC4; }
.gn-qa-title { font-size: 13px; font-weight: 600; color: #1e1e2e; }
.gn-qa-sub   { font-size: 12px; color: #6b7280; margin-top: 2px; }

/* ── EMPTY STATE ── */
.gn-empty {
  font-size: 13px;
  color: #9ca3af;
  padding: 20px 0;
  text-align: center;
}

/* ── RESPONSIVE ── */
@media (max-width: 1100px) {
  .gn-cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 860px) {
  .gn-grid    { grid-template-columns: 1fr; }
  .gn-qa-grid { grid-template-columns: 1fr; }
  .gn-cards   { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .gn-cards { grid-template-columns: 1fr; }
  .gn-main  { padding: 16px; }
  .gn-banner { padding: 24px 20px 20px; }
}

sp_widget.script:
(function() {
	data.sideBar = $sp.getWidget('sidebar_dashboard');
	var userId   = gs.getUserID();
  var userName = gs.getUserDisplayName();

  data.user = { name: userName || 'User', sys_id: userId || '' };
  data.totalApplications  = 0;
  data.newThisMonth       = 0;
  data.pendingAwards      = 0;
  data.activeProjects     = 0;
  data.awardsReceived     = 0;
  data.recentApplications = [];
  data.openPrograms       = [];

  // Total Applications
  try {
    var appGR = new GlideRecord('x_enno_gatenow_service_applicants');
    appGR.addQuery('sys_created_by', gs.getUserName());
    appGR.query();
    while (appGR.next()) { data.totalApplications++; }
  } catch(e) { gs.debug('Dashboard-totalApps: ' + e.message); }

  // New This Month
  try {
    var monthAgo = new GlideDateTime();
    monthAgo.addMonthsLocalTime(-1);
    var newGR = new GlideRecord('x_enno_gatenow_service_applicants');
    newGR.addQuery('sys_created_by', gs.getUserName());
    newGR.addQuery('sys_created_on', '>=', monthAgo.getValue());
    newGR.query();
    while (newGR.next()) { data.newThisMonth++; }
  } catch(e) { gs.debug('Dashboard-newThisMonth: ' + e.message); }

  // Active Projects (Fixed)
  try {
    var projectGR = new GlideRecord('pm_project');
    projectGR.addActiveQuery();
    // Dot-walking to find projects where the linked applicant record points to the logged-in user
    projectGR.addQuery('x_enno_gatenow_applicant.user', userId); 

    projectGR.query();

    // Add the while loop to actually count the records
    while (projectGR.next()) { 
        data.activeProjects++; 
    }
  } catch(e) { gs.debug('Dashboard-activeProjects: ' + e.message); }

  // ── Step 1: Get applicant sys_ids where user = current logged-in user ──
  var applicantIds = [];
  try {
    var applicantGR = new GlideRecord('x_enno_gatenow_service_applicants');
    applicantGR.addQuery('user', userId);  // 'user' is the reference field pointing to sys_user
    applicantGR.query();
    while (applicantGR.next()) {
      applicantIds.push(applicantGR.getUniqueValue());
    }
  } catch(e) { gs.debug('Dashboard-applicantIds: ' + e.message); }

  // Removed the line that was resetting data.activeProjects = 0; here

  if (applicantIds.length > 0) {
    var idString = applicantIds.join(',');

    // Pending Awards
    try {
      var pendingGR = new GlideRecord('x_enno_gatenow_grant_awards');
      pendingGR.addQuery('applicant', 'IN', idString);
      pendingGR.addQuery('applicant_response', 'Pending');
      pendingGR.query();
      while (pendingGR.next()) { data.pendingAwards++; }
    } catch(e) { gs.debug('Dashboard-pendingAwards: ' + e.message); }

  } else {
    gs.debug('Dashboard-awards: No applicant records found for user: ' + userId);
  }

  // Recent Applications
  try {
    var recGR = new GlideRecord('x_enno_gatenow_service_applicants');
    recGR.addQuery('sys_created_by', gs.getUserName());
    recGR.orderByDesc('sys_updated_on');
    recGR.setLimit(5);
    recGR.query();
    while (recGR.next()) {
      data.recentApplications.push({
        number:         recGR.getValue('number') || '',
        program_name:   recGR.getDisplayValue('program') || '',
        state:          recGR.getValue('state') || '',
        state_display:  recGR.getDisplayValue('state') || '',
        sys_updated_on: recGR.getDisplayValue('sys_updated_on') || ''
      });
    }
  } catch(e) { gs.debug('Dashboard-recentApps: ' + e.message); }

  // Open Programs
  try {
    var progGR = new GlideRecord('x_enno_gatenow_grant_program');
    progGR.addQuery('status', 'accepting_proposals');
    progGR.orderBy('proposal_close_date');
    progGR.setLimit(5);
    progGR.query();
    while (progGR.next()) {
      data.openPrograms.push({
        name:              progGR.getValue('program_name') || '',
        short_description: progGR.getValue('program_description') || '',
        budget:            progGR.getDisplayValue('program_budget') || '',
        close_date:        progGR.getDisplayValue('proposal_close_date') || ''
      });
    }
  } catch(e) { gs.debug('Dashboard-openPrograms: ' + e.message); }

})();
